#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  # q holds the quote: bash 3.2 (macOS) keeps the backslash of a \' replacement.
  local line value sq="'\\''" q="'"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/$q}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# feedr connectors setup: lets claude.ai (web, desktop and the phone app) and Grok Bot use feedr's
# MCP server, signing in with Clerk over OAuth. It gives the Railway API its two OAuth variables,
# registers the MCP server in Clerk, then walks you through adding each connector and checking that
# it lists feedr's tools. Run it from the repo root after the OAuth PR has merged:
# ./scripts/connectors-setup.sh. Safe to re-run: every check is repeated and finished stages say so.

run_wizard() {

TOTAL_STAGES=8

cd "$(dirname "$0")/.."
ENV_FILE=.env.deploy
MOBILE_ENV=apps/mobile/.env.local
PR_URL="https://github.com/benjamingriff/feedr/pulls?q=is%3Apr+oauth"

# ── Helpers for clear stage screens (as in scripts/deploy-setup.sh) ──────
what() { printf '  %sWhat this does:%s %s\n' "$BOLD" "$RESET" "$1"; }
you()  { printf '  %sYour part:%s %s\n\n' "$BOLD" "$RESET" "$1"; }
ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
die()  { printf '\n'; warn "$1"; printf '\n'; exit 1; }
# copy VALUE puts a value on the clipboard.
copy() {
  if command -v wl-copy >/dev/null 2>&1; then printf '%s' "$1" | wl-copy
  elif command -v pbcopy >/dev/null 2>&1; then printf '%s' "$1" | pbcopy
  elif command -v xclip >/dev/null 2>&1; then printf '%s' "$1" | xclip -selection clipboard
  else return 1; fi
}
# status URL [method]: the HTTP status code, or 000 when nothing answers.
status() { curl -sS -o /dev/null -w '%{http_code}' --max-time 10 -X "${2:-GET}" "$1" 2>/dev/null || true; }
# metadata: the API's protected-resource metadata, or nothing.
metadata() { curl -fsS --max-time 10 "$API/.well-known/oauth-protected-resource/mcp" 2>/dev/null || true; }
# oauth_ready: the metadata names /mcp exactly as the resource.
oauth_ready() { [[ "$(metadata | jq -r '.resource // empty' 2>/dev/null)" == "$API/mcp" ]]; }
# challenge: the WWW-Authenticate header of an unauthenticated POST /mcp.
challenge() {
  curl -sS -o /dev/null -D - --max-time 10 -X POST "$API/mcp" 2>/dev/null \
    | tr -d '\r' | sed -n 's/^[Ww][Ww][Ww]-[Aa]uthenticate: //p'
}
# clerk_ready: Clerk's metadata lists S256 and client ID metadata documents (public clients).
clerk_ready() {
  curl -fsS --max-time 10 "$ISSUER/.well-known/oauth-authorization-server" 2>/dev/null | jq -e '
    (.code_challenge_methods_supported | index("S256")) and .client_id_metadata_document_supported == true
  ' >/dev/null 2>&1
}
# wait_for CHECK "what": retries CHECK every 10s for 5 minutes. Fails if it never passes.
wait_for() {
  printf '  Waiting for %s' "$2"
  for _ in $(seq 1 30); do "$1" && { printf '\n'; return 0; }; printf '.'; sleep 10; done
  printf '\n'; return 1
}
# tools_check "where": the end-to-end check, recorded if it didn't pass.
tools_check() {
  say "In $1, start a new chat with feedr turned on and send:"
  printf '\n      %sUse feedr to list my people, then tell me how many tools feedr has.%s\n\n' "$BOLD" "$RESET"
  say "It should name the people in your account and count about 24 tools."
  if confirm "Did $1 list feedr's tools and your people?"; then ok "$1 works"
  else
    SKIPPED+=("$1: feedr didn't list its tools. Re-run this wizard: it repeats every check.")
    warn "Re-run this wizard to repeat the checks. If they all pass, the problem is on the client's"
    say  "  side: claude.ai's OAuth flow has open bugs (github.com/anthropics/claude-ai-mcp issues"
    say  "  410 and 215). Removing the connector and adding it again sometimes clears it."
  fi
}

for tool in curl jq; do command -v "$tool" >/dev/null 2>&1 || die "Install $tool first."; done

banner "feedr connectors setup"

# ── 1. The API ────────────────────────────────────────────────────────────
stage "The API's address"
what "finds the production API, which connectors will reach at its /mcp path."
you "check the address, or paste it (Railway → api service → Settings → Networking)."
while :; do
  ask FEEDR_API_URL "The API's https:// address:" || die "No address given."
  FEEDR_API_URL=${FEEDR_API_URL%/}
  [[ "$FEEDR_API_URL" == https://* ]] || { warn "Use the https:// address."; continue; }
  [[ "$(status "$FEEDR_API_URL/health")" == 200 ]] && break
  warn "Nothing answers at $FEEDR_API_URL/health. Check Railway's api service, or the address."
done
write_env FEEDR_API_URL "$FEEDR_API_URL"
API=$FEEDR_API_URL
ok "The API answers at $API"
printf '\n'; pause

# ── 2. The OAuth change is live ───────────────────────────────────────────
stage "Railway: the OAuth change is deployed"
what "checks that Railway is running the API with OAuth on /mcp. Railway deploys"
say  "                each commit on main once CI passes."
# The old API answers every unknown path with 401; the new one serves the metadata (200), or 404
# until its variables are set.
code=$(status "$API/.well-known/oauth-protected-resource/mcp")
if [[ "$code" == 200 || "$code" == 404 ]]; then
  you "nothing."
  ok "Railway runs the OAuth change"
else
  you "merge the OAuth PR, then wait here while Railway deploys it."
  open_url "$PR_URL"
  deployed() { local c; c=$(status "$API/.well-known/oauth-protected-resource/mcp"); [[ "$c" == 200 || "$c" == 404 ]]; }
  if wait_for deployed "the deploy"; then ok "Railway runs the OAuth change"
  else die "Still the old API. Check the PR merged and Railway's Deployments tab, then re-run."; fi
fi
printf '\n'; pause

# ── 3. Railway variables ──────────────────────────────────────────────────
stage "Railway: two variables"
what "gives the API Clerk's publishable key, which names the Clerk sign-in"
say  "                server, and its own public address, which is the MCP URL tokens must be for."
if oauth_ready; then
  you "nothing."
  ok "OAuth is on: the metadata names $API/mcp"
else
  pk=$(ENV_FILE=$MOBILE_ENV _existing EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY || true)
  if [[ -z "$pk" ]]; then
    note "Clerk's publishable key isn't in $MOBILE_ENV. It's in Clerk → feedr → Development → API keys,"
    note "or Expo → feedr → Environment variables (EXPO_PUBLIC_CLERK_PUBLISHABLE_KEY)."
    while :; do ask pk "Paste the publishable key (pk_test_…):" || die "No key given."; [[ "$pk" == pk_* ]] && break; warn "It starts pk_."; done
  fi
  you "add these in Railway → your project → api service → Variables → New Variable."
  if copy "$pk"; then step "CLERK_PUBLISHABLE_KEY, and paste. It's on your clipboard:"
  else step "CLERK_PUBLISHABLE_KEY with this value:"; fi
  note "      $pk"
  step "PUBLIC_URL with this value (no /mcp, no trailing slash):"
  note "      $API"
  step "Deploy the changes when Railway offers to."
  open_url "https://railway.com/dashboard"
  printf '\n'; pause "Press Enter once you've deployed."
  if wait_for oauth_ready "the API to serve its OAuth metadata"; then ok "OAuth is on: the metadata names $API/mcp"
  else
    warn "The metadata says: $(metadata || echo 'nothing')"
    die "Check both variables are on the api service and spelled exactly, then re-run."
  fi
fi
ISSUER=$(metadata | jq -r '.authorization_servers[0]')
printf '\n'
say "The two checks a connector makes first:"
note "  curl -i -X POST $API/mcp"
note "    → 401, WWW-Authenticate: $(challenge)"
note "  curl $API/.well-known/oauth-protected-resource/mcp"
note "    → resource $(metadata | jq -r .resource), authorization server $ISSUER"
printf '\n'; pause

# ── 4. Clerk: the MCP server ──────────────────────────────────────────────
stage "Clerk: register the MCP server"
what "tells Clerk about feedr's MCP server, so it issues tokens for that URL"
say  "                and lets clients like Claude register themselves (public clients)."
if clerk_ready; then
  you "nothing."
  ok "Clerk lists S256 and accepts public clients"
else
  you "follow these steps. Production uses Clerk's development instance, so pick that."
  open_url "https://dashboard.clerk.com/~/agents/mcp-servers"
  step "Check the top bar says the feedr app and Development."
  step "Add MCP server (or Get started). MCP URL:"
  note "      $API/mcp"
  copy "$API/mcp" && note "      (on your clipboard)"
  step "Turn on Allow public clients to connect, then Add server."
  step "Then Configure → OAuth applications → Settings: check Include Audience is on."
  say  "           Clerk turns it on with the first MCP server; without it tokens carry no audience"
  say  "           and the API refuses them."
  printf '\n'; pause "Press Enter once the server is added."
  if wait_for clerk_ready "Clerk's metadata to list public clients"; then ok "Clerk lists S256 and accepts public clients"
  else
    warn "Clerk's metadata at $ISSUER/.well-known/oauth-authorization-server doesn't list"
    warn "client_id_metadata_document_supported yet. Check Allow public clients is on."
    SKIPPED+=("Clerk: turn on public clients for the MCP server $API/mcp")
  fi
fi
note "  curl $ISSUER/.well-known/oauth-authorization-server | jq .code_challenge_methods_supported"
printf '\n'; pause

# ── 5. claude.ai ──────────────────────────────────────────────────────────
stage "claude.ai: add the connector"
what "adds feedr to your Claude account. Connectors follow your account, so this"
say  "                also covers the desktop and phone apps (next stage)."
you "follow these steps."
open_url "https://claude.ai/settings/connectors"
step "Add custom connector. Name: feedr. Remote MCP server URL:"
note "      $API/mcp"
copy "$API/mcp" && note "      (on your clipboard)"
step "Add, then Connect. Clerk's sign-in page opens: continue with Apple or Google, the same"
say  "           login as the app, so the connector sees your recipes. Clerk's development"
say  "           banner on that page is expected. Allow access when asked."
step "Back in claude.ai, feedr shows as connected. Its tools are listed under it."
printf '\n'; pause "Press Enter once it says connected."
tools_check "claude.ai"
printf '\n'; pause

# ── 6. Claude desktop and phone ───────────────────────────────────────────
stage "Claude desktop and phone apps"
what "checks the connector reached the apps. There's nothing to add: they use"
say  "                the connector from your account."
you "open each app signed in to the same Claude account."
step "Desktop: new chat → the tools (+ or sliders) menu → turn feedr on."
step "Phone: new chat → + → Connectors (or Tools) → turn feedr on."
say  "If either asks you to connect again, sign in with the same Apple or Google login."
printf '\n'
tools_check "the Claude phone app"
tools_check "Claude desktop"
printf '\n'; pause

# ── 7. The app ────────────────────────────────────────────────────────────
stage "The app: Agent access is hidden"
what "sends the app change (Agent access hidden on Account) to your phone. It's"
say  "                JavaScript only, so Release publishes an over-the-air update, no TestFlight build."
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1 && confirm "Run the Release workflow on main now?"; then
  gh workflow run release.yml --ref main
  sleep 5
  run_id=$(gh run list --workflow release.yml --limit 1 --json databaseId -q '.[0].databaseId')
  gh run watch "$run_id" --exit-status || warn "The release failed. Follow its summary: gh run view $run_id --web"
else
  note "Run it later from GitHub → Actions → Release, or: gh workflow run release.yml --ref main"
  SKIPPED+=("Run Release so the phone gets the hidden Agent access")
fi
you "once it's published, close and reopen the app twice (the update loads on the next launch)."
step "Account: no Agent access section between Timers & reminders and Sign-in & data."
step "Long-press the ID line under your name: Agent access appears. Long-press again to hide it."
if ! confirm "Does Agent access hide and show like that?"; then
  SKIPPED+=("The app: Agent access didn't hide or show on long-press")
fi
printf '\n'; pause

# ── 8. Grok Bot ───────────────────────────────────────────────────────────
stage "Grok Bot: add the connector"
what "adds feedr to Grok Bot. Its connector dialog isn't documented: a community"
say  "                guide says it takes a server URL, optional headers and an optional OAuth"
say  "                client ID. Try these in order and stop at the first that lists the tools."
you "open Grok Bot's custom connector settings."
step "1. URL only: $API/mcp. If it opens Clerk's sign-in, use the same Apple or Google login."
step "2. If it asks for an OAuth client ID: Clerk → feedr → Development → OAuth applications →"
say  "      Add OAuth application, named Grok Bot, with Grok's callback URL as the redirect URI"
say  "      (Grok's dialog or its error message shows it) and the profile scope. If Grok has no"
say  "      field for a client secret, make it a public client. Paste its Client ID into Grok."
step "3. Or a header: in the feedr app, long-press your account ID on Account → Create token,"
say  "      then add the header  Authorization: Bearer feedr_…  in Grok."
open_url "https://dashboard.clerk.com/~/oauth-applications"
printf '\n'
if confirm "Has Grok Bot connected?"; then
  tools_check "Grok Bot"
else
  SKIPPED+=("Grok Bot: connect it with one of the three options, then ask it to list feedr's tools")
fi
printf '\n'; pause "Press Enter to finish."

finish
note "Personal tokens still work for Claude Code and pnpm smoke:mcp."
printf '\n'
}

run_wizard "$@"; exit
